"""Deterministic review views only; no artistic image edits."""
import argparse,json,math,pathlib,hashlib
import cv2,numpy as np
p=argparse.ArgumentParser();p.add_argument('--panorama',required=True);p.add_argument('--out',required=True);p.add_argument('--camera',default='{"yaw":0,"pitch":0,"fov":65}');a=p.parse_args();out=pathlib.Path(a.out);out.mkdir(parents=True,exist_ok=True);im=cv2.imread(a.panorama);camera=json.loads(a.camera)
views=[('front',camera['yaw'],camera['pitch'],camera['fov']),('right',math.pi/2,0,90),('rear',math.pi,0,90),('left',-math.pi/2,0,90),('up',0,math.pi/2,110),('down',0,-math.pi/2,110),('rear-up',math.pi,.8,90),('rear-down',math.pi,-.8,90),('front-down',0,-.8,90)];tiles=[];records=[]
for name,y,p,fov in views:
 w,h=640,360;t=math.tan(math.radians(fov/2));f=np.array([math.sin(y)*math.cos(p),math.cos(y)*math.cos(p),math.sin(p)]);r=np.array([math.cos(y),-math.sin(y),0]);u=np.array([-math.sin(y)*math.sin(p),-math.cos(y)*math.sin(p),math.cos(p)]);yy,xx=np.mgrid[:h,:w];q=f+(2*(xx+.5)/w-1)[...,None]*t*w/h*r+(1-2*(yy+.5)/h)[...,None]*t*u;q/=np.linalg.norm(q,axis=-1,keepdims=True);mx=((np.arctan2(q[...,0],q[...,1])/(2*math.pi)+.5)*im.shape[1]-.5).astype('float32');my=((.5-np.arcsin(q[...,2])/math.pi)*im.shape[0]-.5).astype('float32');v=cv2.remap(im,mx,my,cv2.INTER_LINEAR,borderMode=cv2.BORDER_WRAP);cv2.imwrite(str(out/(name+'.png')),v);label=np.zeros((30,w,3),np.uint8);cv2.putText(label,name,(8,22),cv2.FONT_HERSHEY_SIMPLEX,.6,(255,255,255),1);tiles.append(np.vstack([label,v]));records.append({'id':name,'yaw':y,'pitch':p,'fov':fov,'size':[w,h]})
cv2.imwrite(str(out/'directions.jpg'),np.vstack([np.hstack(tiles[i:i+3]) for i in range(0,9,3)]),[cv2.IMWRITE_JPEG_QUALITY,92]);(out/'directions.json').write_text(json.dumps({'input':a.panorama,'sha256':hashlib.sha256(pathlib.Path(a.panorama).read_bytes()).hexdigest(),'operation':'Perspective sampling for review, labels only on contact sheet','views':records},indent=2)+'\n')
